  foreach(var kind in new[]{DrunkRideCase.Normal,DrunkRideCase.Vomit,DrunkRideCase.Sleepy,DrunkRideCase.Both}){var ride=DrunkRideState.Create("fixed-"+kind,true,kind);Check(ride.IsDrunk==(kind!=DrunkRideCase.Normal),"fixed normal/drunk");Check(ride.VomitProgress>=.3f&&ride.VomitProgress<=.7f,"vomit progress range");Check(!ride.Advance(10,.29f),"never before30 percent");bool vomit=ride.Advance(10,.71f);Check(vomit==(kind==DrunkRideCase.Vomit||kind==DrunkRideCase.Both),"fixed vomit");Check(!ride.Advance(1,1),"vomit single event");Check(ride.Arrive(true)&&!ride.Arrive(false),"first arrival immutable");var copy=ride.Copy();Check(copy.ArrivalElapsed==21&&copy.OnTime,"saved arrival time");bool sleepy=kind==DrunkRideCase.Sleepy||kind==DrunkRideCase.Both;Check(copy.Waiting==sleepy,"independent sleep selection");if(sleepy){Check(!copy.Disembark(true,true),"wake at0 rejected");copy.Advance(14.99f,1);Check(!copy.Disembark(true,true),"wake before15 rejected");copy.Advance(.01f,1);Check(!copy.Disembark(false,true),"unsafe departure blocked");Check(copy.Disembark(true,true)&&!copy.Disembark(true,true),"wake15 single settlement");var auto=ride.Copy();auto.Advance(30,1);Check(!auto.Disembark(false,false)&&auto.Disembark(true,false),"30 seconds wait returns to safe stop");}else Check(copy.Disembark(true,false),"ordinary immediate disembark");}
  int drunkCount=0,vomitCount=0,sleepCount=0;for(int i=0;i<10000;i++){var r=DrunkRideState.Create("candidate"+i,true);var same=DrunkRideState.Create("candidate"+i,true);Check(r.IsDrunk==same.IsDrunk&&r.SleepPlanned==same.SleepPlanned&&r.VomitProgress==same.VomitProgress,"stable repeated candidate");if(r.IsDrunk){drunkCount++;if(r.VomitPlanned)vomitCount++;if(r.SleepPlanned)sleepCount++;}}Check(drunkCount>1700&&drunkCount<2300,"20 percent candidate probability");Check(vomitCount>drunkCount*.20&&vomitCount<drunkCount*.30,"25 percent conditional vomit");Check(sleepCount>drunkCount*.25&&sleepCount<drunkCount*.35,"30 percent conditional sleep");Check(!DrunkRideState.Create("fixed",false,DrunkRideCase.Both).IsDrunk,"daily cap suppresses drunk candidate");
  var trip=new FareTrip();trip.Accept(5000,1);trip.Board();trip.Tick(.5f);Check(trip.LockArrival(),"lock first valid arrival");trip.Tick(30);Check(trip.Remaining==.5f&&trip.ArrivedOnTime,"deadline freeze while business time advances");var saved=trip.Snapshot();var resume=new FareTrip();resume.Restore(saved);Check(resume.ArrivalLocked&&resume.Complete()==5000&&resume.Complete()==0,"arrival freeze save and one-time fare");trip.Clear();trip.Accept(5000,1);trip.Board();trip.Tick(2);trip.LockArrival();Check(!trip.ArrivedOnTime&&trip.Complete()==0&&trip.State==TripState.Failed,"late before arrival zero");
  var settings=PrototypeSettings.ForThreeDays();settings.startCash=500;var economy=new EconomyLedger(settings);economy.Care.Finish("dirty",true);double before=economy.Elapsed;Check(economy.UseWash("wash1"),"wash affordable through debt");Check(economy.Elapsed==before+30&&economy.Care.Cleanliness==100,"wash30seconds clean100");Check(economy.Account.Cash==0&&economy.Account.Debt==1500&&economy.Account.Expense(1,"wash")==2000,"wash paid500 debt1500 expense2000");Check(!economy.UseWash("wash1")&&economy.Elapsed==30&&economy.Account.Expense(1,"wash")==2000,"duplicate wash no cost/time");var finance=CampaignAccount.Restore(economy.Account.Snapshot());Check(!finance.Wash("wash1",1)&&finance.Debt==1500,"wash identity survives restore");economy.Advance(economy.SecondsLeft-29,0);Check(economy.UseWash("wash2")&&economy.Account.Expense(1,"wash")==4000,"wash may enter overtime with one charge");
  var exact=new EconomyLedger(settings);exact.Advance(exact.SecondsLeft-30,0);Check(exact.UseWash("boundary")&&exact.State==BusinessState.Open,"exactly30seconds wash remains open");
